def precisions_at_relevant_positions(ranked_results, relevant_set):
    precisions = []
    hits = 0
    for i, item in enumerate(ranked_results, start=1):
        if item in relevant_set:
            hits += 1
            precisions.append(hits / i)
    return precisions

results = ["a", "b", "c", "d", "e"]
relevant = {"a", "c", "e"}
print(precisions_at_relevant_positions(results, relevant))   # [1.0, 0.667, 0.6]

